#include <iostream>

int main()
{
    int cents{};
    std::cin >> cents;

    int quarters{ cents / 25 };
    cents = cents % 25;
    int dimes{ cents / 10 };
    cents = cents % 10;
    int nickels{ cents / 5 };
    cents = cents % 5;

    std::cout << "Quarters: " << quarters << '\n';
    std::cout << "Dimes: " << dimes << '\n';
    std::cout << "Nickels: " << nickels << '\n';
    std::cout << "Pennies: " << cents << '\n';
    return 0;
}
